import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Calendar arithmetic for recurring issues.
 *
 * Occurrence days are `YYYY-MM-DD` strings and are only ever compared as
 * calendar days, never as instants: "day D has started" means the wall clock
 * in the rule's own time zone has reached 00:00 on D. Because a wall clock
 * only shows date D once it has reached D 00:00 (a spring-forward gap that
 * swallows midnight jumps straight past it), that is the same as "the local
 * date is at least D" — which keeps daylight-saving shifts out of the maths.
 */

const YMD_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const DAY_MS = 86_400_000;

/** Days since the epoch for a calendar day; `Date.UTC` would mangle years < 100. */
function dayNumber(year: number, month: number, day: number): number {
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getTime() / DAY_MS;
}

function parseDay(value: string): number | null {
  const match = YMD_PATTERN.exec(value);
  if (match === null) return null;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  const days = dayNumber(year, month, day);
  const back = new Date(days * DAY_MS);
  const isReal =
    back.getUTCFullYear() === year &&
    back.getUTCMonth() === month - 1 &&
    back.getUTCDate() === day;

  return isReal ? days : null;
}

function formatDay(days: number): string {
  return new Date(days * DAY_MS).toISOString().slice(0, 10);
}

/** ISO weekday of a day number: 1 = Monday … 7 = Sunday (day 0 was a Thursday). */
function isoWeekday(days: number): number {
  return ((((days % 7) + 7) % 7) + 3) % 7 + 1;
}

/** True for a `YYYY-MM-DD` string naming a day that exists (no `2026-02-30`). */
export function isRealCalendarDate(value: string): boolean {
  return parseDay(value) !== null;
}

/**
 * True when the runtime's tz database knows `value` as a zone name. Offset
 * spellings such as `+05:00` are accepted by `Intl` but are not IANA zones.
 */
export function isKnownTimeZone(value: string): boolean {
