/**
 * Recurring-issue rules. Every tenant read filters by `orgId`; the job's
 * work list is the one deliberate cross-tenant read.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId, UserId } from "@/types/common";
import type { RecurringIssue } from "@/types/recurring-issue";

/** Rules are read back in the order they were written. */
const CREATION_ORDER = asc(sql`rowid`);

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}

/**
 * The job's work list: every organization's rules that are not paused.
 * Cross-tenant on purpose — a background worker is not a request.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}

/** The `recurringIssues` quota compares against this; paused rules count. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/**
 * Stores a new rule unless `hasRoom` says the organization is already at its
 * cap, returning `null` in that case. The count and the insert share one
 * synchronous write transaction, so two creations racing for the last slot
 * cannot both win.
 */
export async function insertRecurringIssueIfRoom(
  input: CreateRecurringIssueInput,
  createdBy: UserId,
  hasRoom: (used: number) => boolean,
): Promise<RecurringIssue | null> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb().transaction(
    (tx) => {
      const used = tx
        .select({ value: count() })
        .from(recurringIssues)
        .where(orgPredicate(recurringIssues.orgId, input.orgId as OrgId))
        .get();

      if (!hasRoom(used?.value ?? 0)) return null;

      return tx
        .insert(recurringIssues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          title: input.title,
          priority: input.priority ?? "none",
          assigneeId: input.assigneeId ?? null,
          cadence: input.cadence,
          weekday: input.weekday ?? null,
          timezone: input.timezone,
          startsOn: input.startsOn,
          lastOccurrenceOn: null,
          paused: false,
          createdBy,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
    },
    { behavior: "immediate" },
  );

  return row ? toRecurringIssue(row) : null;
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) {
    throw new Error(`Recurring issue ${recurringIssueId} not found in org ${orgId}`);
  }
  return toRecurringIssue(row);
}

/** Records the occurrence day the job last filed an issue for. */
export async function setLastOccurrenceOn(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({
      lastOccurrenceOn: occurrenceOn,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) {
    throw new Error(`Recurring issue ${recurringIssueId} not found in org ${orgId}`);
  }
  return toRecurringIssue(row);
}
