/**
 * Files an ordinary issue for every recurring-issue rule that has come due, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, can, latestOccurrenceOn, isArchived
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { latestOccurrenceOn } from "@/lib/recurrence";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource, requireFound } from "@/server/services/_support";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

type RuleOutcome = "created" | "paused" | "skipped";

const logger = createLogger("recurring-issue-job");

/**
 * Rules being worked on right now. Two overlapping runs would otherwise both
 * read the same `lastOccurrenceOn` and each file the occurrence.
 */
const inFlight = new Set<string>();

/**
 * One pass over every non-paused rule of every organization. A rule files at
 * most one issue per run — for the latest occurrence that has started — and
 * one rule failing never stops the rest. `processed` counts issues created.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRecurringIssues();

    for (const { id, orgId } of rules) {
      if (inFlight.has(id)) continue;
      inFlight.add(id);

      try {
        if ((await fileOccurrence(orgId, id, now)) === "created") {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: id,
          reason: error instanceof Error ? error.message : String(error),
        });
      } finally {
        inFlight.delete(id);
      }
    }
  });
}

async function fileOccurrence(
  orgId: OrgId,
  recurringIssueId: string,
  now: Date,
): Promise<RuleOutcome> {
  // Re-read: the rule may have been paused or advanced since the work list.
  const rule = await recurringRepo.findRecurringIssueById(
    orgId,
    recurringIssueId,
  );
  if (rule === null || rule.paused) return "skipped";

  const occurrence = latestOccurrenceOn(rule, now);
  if (
    occurrence === null ||
    (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn)
  ) {
    return "skipped";
  }

  const project = requireFound(
    await projectRepo.findProjectById(orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  // Nothing to file into; the next run after a restore picks the then-latest.
  if (isArchived(project)) return "skipped";

  const creator = await memberRepo.findActiveMember(orgId, rule.createdBy);
  const actor: Actor | null =
    creator === null
      ? null
      : { userId: rule.createdBy, orgId, role: creator.role };

  if (actor === null || !can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setRecurringIssuePaused(orgId, rule.id, true);
    return "paused";
  }

  const assignee =
    rule.assigneeId === null
      ? null
      : await memberRepo.findActiveMember(orgId, rule.assigneeId);

  await createIssue(actor, {
    orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId: assignee === null ? null : rule.assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  });

  await recurringRepo.setLastOccurrenceOn(orgId, rule.id, occurrence);
  return "created";
}
