    const rule = { ...daily, timezone: "Pacific/Auckland" };
    // 12:00Z on the 4th is 01:00 on the 5th in Auckland (UTC+13 in March).
    expect(latestOccurrenceOn(rule, new Date("2026-03-04T12:00:00Z"))).toBe("2026-03-05");
    expect(latestOccurrenceOn({ ...daily, timezone: "UTC" }, new Date("2026-03-04T12:00:00Z"))).toBe("2026-03-04");
  });

  it("has none before startsOn", () => {
    const rule = { ...daily, timezone: "UTC" };
    expect(latestOccurrenceOn(rule, new Date("2026-02-28T23:59:59Z"))).toBeNull();
    expect(latestOccurrenceOn(rule, new Date("2026-03-01T00:00:00Z"))).toBe("2026-03-01");
  });

