    const rule = { ...daily, timezone: "America/Los_Angeles" };
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T07:59:59Z"))).toBe("2026-03-07");
    expect(latestOccurrenceOn(rule, new Date("2026-03-08T08:00:00Z"))).toBe("2026-03-08");
    // The 8th is 23 hours long: the 9th starts at 07:00Z, not 08:00Z.
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T06:59:59Z"))).toBe("2026-03-08");
    expect(latestOccurrenceOn(rule, new Date("2026-03-09T07:00:00Z"))).toBe("2026-03-09");
  });

