    // America/Sao_Paulo (2018): clocks went 00:00 → 01:00 on 4 November.
    const rule = { cadence: "daily", weekday: null, startsOn: "2018-01-01", timezone: "America/Sao_Paulo" } as const;
    expect(latestOccurrenceOn(rule, new Date("2018-11-04T02:59:59Z"))).toBe("2018-11-03");
    expect(latestOccurrenceOn(rule, new Date("2018-11-04T03:00:00Z"))).toBe("2018-11-04");
  });

