    // 2026-03-05 is a Thursday.
    const now = new Date("2026-03-05T10:00:00Z");
    const weekly = (weekday: number, startsOn = "2026-01-01") =>
      latestOccurrenceOn({ cadence: "weekly", weekday, timezone: "UTC", startsOn }, now);

