    startsOn: "2026-03-01",
    ...overrides,
  };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  growth = await createTenant("rr-growth", "growth");
  other = await createTenant("rr-other", "growth");
});

afterAll(() => {
  cleanup();
});

describe("plan quota", () => {
  it("is 0 / 3 / 25 / unlimited by plan", () => {
    expect(getPlanLimits("free").recurringIssues).toBe(0);
    expect(getPlanLimits("starter").recurringIssues).toBe(3);
    expect(getPlanLimits("growth").recurringIssues).toBe(25);
    expect(getPlanLimits("enterprise").recurringIssues).toBe(Number.POSITIVE_INFINITY);
  });
});

describe("createRecurringIssue", () => {
  it("stores a fresh, unpaused rule owned by the actor", async () => {
    const created = await service.createRecurringIssue(
      growth.actors.member,
      rule(growth, {
        title: "Monday planning",
        cadence: "weekly",
        weekday: 1,
        priority: "high",
        assigneeId: growth.userIds.admin,
      }),
    );

    expect(created).toMatchObject({
      orgId: growth.org.id,
      projectId: growth.project.id,
      title: "Monday planning",
      priority: "high",
      assigneeId: growth.userIds.admin,
      cadence: "weekly",
      weekday: 1,
      timezone: "UTC",
      startsOn: "2026-03-01",
      lastOccurrenceOn: null,
      paused: false,
      createdBy: growth.userIds.member,
    });
    await expect(
      recurringRepo.findRecurringIssueById(growth.org.id, created.id),
    ).resolves.toEqual(created);
  });

  it("rejects invalid input with the ZodError and stores nothing", async () => {
    const before = await recurringRepo.countRecurringIssues(growth.org.id);
    await expect(
      service.createRecurringIssue(growth.actors.member, rule(growth, { cadence: "weekly" })),
    ).rejects.toBeInstanceOf(ZodError);
    await expect(
      service.createRecurringIssue(growth.actors.member, rule(growth, { startsOn: "2026-02-30" })),
    ).rejects.toBeInstanceOf(ZodError);
    await expect(recurringRepo.countRecurringIssues(growth.org.id)).resolves.toBe(before);
  });

  it("enforces tenant scope, project existence, archive state and permission", async () => {
    await expect(
      service.createRecurringIssue(growth.actors.member, rule(other)),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      service.createRecurringIssue(
        growth.actors.member,
        rule(growth, { projectId: other.project.id }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      service.createRecurringIssue(growth.actors.viewer, rule(growth)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const archived = await createTenant("rr-archived", "growth");
    await projectRepo.archiveProject(archived.org.id, archived.project.id);
    await expect(
      service.createRecurringIssue(archived.actors.member, rule(archived)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("requires an active member as the assignee", async () => {
    const tenant = await createTenant("rr-assignee", "growth");

    await expect(
      service.createRecurringIssue(
        tenant.actors.member,
        rule(tenant, { assigneeId: other.userIds.member }),
      ),
    ).rejects.toThrow();

    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberRepo.archiveMember(tenant.org.id, member!.id);
    await expect(
      service.createRecurringIssue(
        tenant.actors.member,
        rule(tenant, { assigneeId: tenant.userIds.viewer }),
      ),
    ).rejects.toThrow();

    await expect(recurringRepo.countRecurringIssues(tenant.org.id)).resolves.toBe(0);
  });

  it("caps the rules per plan, counting paused ones", async () => {
    const starter = await createTenant("rr-starter", "starter");
    const ids: string[] = [];
    for (let n = 0; n < 3; n += 1) {
      ids.push((await service.createRecurringIssue(starter.actors.member, rule(starter))).id);
    }
    await service.setRecurringIssuePaused(starter.actors.member, {
      orgId: starter.org.id,
      recurringIssueId: ids[0]!,
      paused: true,
    });

    await expect(
      service.createRecurringIssue(starter.actors.member, rule(starter)),
    ).rejects.toThrow();
    await expect(recurringRepo.countRecurringIssues(starter.org.id)).resolves.toBe(3);

    const free = await createTenant("rr-free", "free");
    await expect(
      service.createRecurringIssue(free.actors.member, rule(free)),
    ).rejects.toThrow();
    await expect(recurringRepo.countRecurringIssues(free.org.id)).resolves.toBe(0);
  });

  it("does not let concurrent creations overshoot the cap", async () => {
    const starter = await createTenant("rr-race", "starter");
    const settled = await Promise.allSettled(
      Array.from({ length: 6 }, () =>
        service.createRecurringIssue(starter.actors.member, rule(starter)),
      ),
    );

    expect(settled.filter((result) => result.status === "fulfilled")).toHaveLength(3);
    await expect(recurringRepo.countRecurringIssues(starter.org.id)).resolves.toBe(3);
  });

  it("has no cap on enterprise", async () => {
    const enterprise = await createTenant("rr-enterprise", "enterprise");
    for (let n = 0; n < 30; n += 1) {
      await service.createRecurringIssue(enterprise.actors.member, rule(enterprise));
    }
    await expect(recurringRepo.countRecurringIssues(enterprise.org.id)).resolves.toBe(30);
  });
});

describe("setRecurringIssuePaused", () => {
  it("pauses and resumes for anyone who may create issues", async () => {
    const created = await service.createRecurringIssue(growth.actors.member, rule(growth));
    const input = { orgId: growth.org.id, recurringIssueId: created.id };

    await expect(
      service.setRecurringIssuePaused(growth.actors.member, { ...input, paused: true }),
    ).resolves.toMatchObject({ id: created.id, paused: true });
    await expect(
      service.setRecurringIssuePaused(growth.actors.viewer, { ...input, paused: false }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      service.setRecurringIssuePaused(growth.actors.admin, { ...input, paused: false }),
    ).resolves.toMatchObject({ paused: false });
  });

  it("is a tenant error for another org and not-found for a foreign rule id", async () => {
    const foreign = await service.createRecurringIssue(other.actors.member, rule(other));

    await expect(
      service.setRecurringIssuePaused(growth.actors.member, {
        orgId: other.org.id,
        recurringIssueId: foreign.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      service.setRecurringIssuePaused(growth.actors.member, {
        orgId: growth.org.id,
        recurringIssueId: foreign.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("listRecurringIssues", () => {
  it("lists the org's rules in creation order, for readers too", async () => {
    const tenant = await createTenant("rr-list", "growth");
    const titles = ["Zebra chore", "Alpha chore", "Middle chore"];
    for (const title of titles) {
      await service.createRecurringIssue(tenant.actors.member, rule(tenant, { title }));
