import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import * as service from "@/server/services/recurring-issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

// 2026-03-05 is a Thursday.
const THURSDAY = new Date("2026-03-05T10:00:00Z");

function input(overrides: Partial<CreateRecurringIssueInput> = {}): CreateRecurringIssueInput {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    title: "Daily triage",
    cadence: "daily",
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  };
}

async function issueTitles(t: Tenant = tenant): Promise<string[]> {
  const page = await issueRepo.listIssues({ orgId: t.org.id, limit: 100, cursor: null });
  return page.items.map((issue) => issue.title).sort();
}

async function reload(id: string) {
  return (await recurringRepo.findRecurringIssueById(tenant.org.id, id))!;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

beforeEach(async () => {
  tenant = await createTenant(`rj${Math.random().toString(36).slice(2, 8)}`);
  getDb().$client.prepare("DELETE FROM recurring_issues WHERE org_id != ?").run(tenant.org.id);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
});

afterAll(() => {
  cleanup();
});

describe("the recurring-issue job", () => {
  it("files the latest started occurrence as an ordinary issue", async () => {
    const seen: unknown[] = [];
    detachers.push(subscribe("issue.created", (payload) => void seen.push(payload)));

    const created = await service.createRecurringIssue(
      tenant.actors.member,
      input({ priority: "urgent", assigneeId: tenant.userIds.admin }),
    );
    const result = await runRecurringIssueJob(THURSDAY);

    expect(result).toMatchObject({ kind: "recurring-issues", processed: 1, failed: 0 });
    const [issue] = (
      await issueRepo.listIssues({ orgId: tenant.org.id, limit: 10, cursor: null })
    ).items;
    expect(issue).toMatchObject({
      title: "Daily triage (2026-03-05)",
      projectId: tenant.project.id,
      status: "backlog",
      priority: "urgent",
      description: null,
      dueAt: null,
      labelIds: [],
      assigneeId: tenant.userIds.admin,
      authorId: tenant.userIds.member,
    });
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ actorId: tenant.userIds.member, issueId: issue!.id });
    expect((await reload(created.id)).lastOccurrenceOn).toBe("2026-03-05");
  });

  it("creates nothing on a repeat run and never back-fills missed days", async () => {
    await service.createRecurringIssue(tenant.actors.member, input());

    await runRecurringIssueJob(THURSDAY);
    await expect(runRecurringIssueJob(THURSDAY)).resolves.toMatchObject({ processed: 0 });
    await expect(runRecurringIssueJob(new Date("2026-03-05T23:00:00Z"))).resolves.toMatchObject({
      processed: 0,
    });

    await runRecurringIssueJob(new Date("2026-03-09T00:00:00Z"));
    expect(await issueTitles()).toEqual([
      "Daily triage (2026-03-05)",
      "Daily triage (2026-03-09)",
    ]);
  });

  it("does not double-file when two runs overlap", async () => {
    await service.createRecurringIssue(tenant.actors.member, input());

    await Promise.all([runRecurringIssueJob(THURSDAY), runRecurringIssueJob(THURSDAY)]);

    expect(await issueTitles()).toEqual(["Daily triage (2026-03-05)"]);
  });

  it("files a weekly rule on its ISO weekday, in its own time zone", async () => {
    await service.createRecurringIssue(
      tenant.actors.member,
      input({ title: "Monday planning", cadence: "weekly", weekday: 1 }),
    );
    await service.createRecurringIssue(
      tenant.actors.member,
      input({ title: "Friday wrap", cadence: "weekly", weekday: 5, timezone: "Pacific/Auckland" }),
    );

    // Thu 2026-03-05 10:00Z is Fri 2026-03-06 23:00 in Auckland (NZDT).
    await runRecurringIssueJob(THURSDAY);

    expect(await issueTitles()).toEqual([
      "Friday wrap (2026-03-06)",
      "Monday planning (2026-03-02)",
    ]);
  });

  it("waits for startsOn and for local midnight", async () => {
    const created = await service.createRecurringIssue(
      tenant.actors.member,
      input({ startsOn: "2026-03-08", timezone: "America/Los_Angeles" }),
    );

    await expect(runRecurringIssueJob(new Date("2026-03-08T07:59:59Z"))).resolves.toMatchObject({
      processed: 0,
    });
    await expect(runRecurringIssueJob(new Date("2026-03-08T08:00:00Z"))).resolves.toMatchObject({
      processed: 1,
    });
    expect((await reload(created.id)).lastOccurrenceOn).toBe("2026-03-08");
  });

  it("skips paused rules", async () => {
    const created = await service.createRecurringIssue(tenant.actors.member, input());
    await service.setRecurringIssuePaused(tenant.actors.member, {
      orgId: tenant.org.id,
      recurringIssueId: created.id,
      paused: true,
    });

    await expect(runRecurringIssueJob(THURSDAY)).resolves.toMatchObject({ processed: 0 });
    expect(await issueTitles()).toEqual([]);
  });

  it("leaves a rule alone while its project is archived, then files once it is restored", async () => {
    const created = await service.createRecurringIssue(tenant.actors.member, input());
    await projectRepo.archiveProject(tenant.org.id, tenant.project.id);

    await expect(runRecurringIssueJob(THURSDAY)).resolves.toMatchObject({ processed: 0 });
    expect(await reload(created.id)).toEqual(created);

    await projectRepo.restoreProject(tenant.org.id, tenant.project.id);
    await runRecurringIssueJob(new Date("2026-03-07T09:00:00Z"));
    expect(await issueTitles()).toEqual(["Daily triage (2026-03-07)"]);
  });

  it("pauses the rule when its creator has left the organization", async () => {
    const created = await service.createRecurringIssue(tenant.actors.member, input());
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberRepo.archiveMember(tenant.org.id, member!.id);

    await expect(runRecurringIssueJob(THURSDAY)).resolves.toMatchObject({ processed: 0 });

    expect(await reload(created.id)).toMatchObject({ paused: true, lastOccurrenceOn: null });
    expect(await issueTitles()).toEqual([]);
  });

  it("pauses the rule when its creator can no longer create issues", async () => {
    const created = await service.createRecurringIssue(tenant.actors.member, input());
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberRepo.updateMemberRole(tenant.org.id, member!.id, "viewer");

    await runRecurringIssueJob(THURSDAY);

    expect(await reload(created.id)).toMatchObject({ paused: true, lastOccurrenceOn: null });
    expect(await issueTitles()).toEqual([]);
  });

  it("does not pause a rule that is not due yet", async () => {
    const created = await service.createRecurringIssue(
      tenant.actors.member,
      input({ startsOn: "2026-04-01" }),
    );
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberRepo.archiveMember(tenant.org.id, member!.id);

    await runRecurringIssueJob(THURSDAY);

    expect((await reload(created.id)).paused).toBe(false);
  });

  it("files unassigned when the assignee is no longer an active member", async () => {
    await service.createRecurringIssue(
      tenant.actors.member,
      input({ assigneeId: tenant.userIds.viewer }),
    );
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberRepo.archiveMember(tenant.org.id, viewer!.id);

    await runRecurringIssueJob(THURSDAY);

    const [issue] = (
      await issueRepo.listIssues({ orgId: tenant.org.id, limit: 10, cursor: null })
    ).items;
    expect(issue?.assigneeId).toBeNull();
  });

  it("leaves a refused rule untouched and carries on with the others", async () => {
    // Free plan: 100 issues per project. Rules go in through the repository
    // because the free plan may not create any itself.
    const full = await createTenant(`full${Math.random().toString(36).slice(2, 8)}`, "free");
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(full.org.id, full.project.id, { title: `Seed ${number}` }),
        full.userIds.member,
        number,
      );
    }
    const refused = await recurringRepo.insertRecurringIssueIfRoom(
      {
        orgId: full.org.id,
        projectId: full.project.id,
        title: "No room",
        priority: "none",
        assigneeId: null,
        cadence: "daily",
        weekday: null,
        timezone: "UTC",
        startsOn: "2026-03-01",
      } as never,
      full.userIds.member,
      () => true,
    );
    await service.createRecurringIssue(tenant.actors.member, input());

    const result = await runRecurringIssueJob(THURSDAY);

    expect(result).toMatchObject({ processed: 1, failed: 1 });
    expect(await recurringRepo.findRecurringIssueById(full.org.id, refused!.id)).toEqual(refused);
    expect(await issueTitles()).toEqual(["Daily triage (2026-03-05)"]);

    // Room appears, and the next run tries again.
    getDb().$client.prepare("DELETE FROM issues WHERE org_id = ?").run(full.org.id);
    await runRecurringIssueJob(THURSDAY);
    expect(await issueTitles(full)).toEqual(["No room (2026-03-05)"]);
  });
});

describe("the queue and scheduler wiring", () => {
  it("runs a queued recurring-issues job with the current time", async () => {
    const created = await service.createRecurringIssue(
      tenant.actors.member,
      input({ startsOn: "2020-01-01" }),
    );

    enqueue({
      id: "recurring-issues:test",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });
    await expect(drain()).resolves.toBe(1);

    const today = new Date().toISOString().slice(0, 10);
    expect((await reload(created.id)).lastOccurrenceOn).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(await issueTitles()).toHaveLength(1);
    expect((await reload(created.id)).lastOccurrenceOn! <= today).toBe(true);
  });

  it("is scheduled every 15 minutes", async () => {
    const start = Date.now() - 2 * 3_600_000;
    await tick(new Date(start)); // first tick: every kind is due

    const created = await service.createRecurringIssue(
      tenant.actors.member,
      input({ startsOn: "2020-01-01" }),
    );

    await tick(new Date(start + 14 * 60_000));
    expect((await reload(created.id)).lastOccurrenceOn).toBeNull();

    await tick(new Date(start + 15 * 60_000));
    expect((await reload(created.id)).lastOccurrenceOn).not.toBeNull();
  });
});
